ch((t) => {\n    s.addShape(pres.shapes.RECTANGLE, {\n      x: t.x, y: t.y, w: 2.9, h: 0.85, fill: { color: C.cardBg }, shadow: mkSh(),\n    });\n    s.addShape(pres.shapes.RECTANGLE, {\n      x: t.x, y: t.y, w: 0.06, h: 0.85, fill: { color: C.accent2 },\n    });\n    s.addText(t.name, {\n      x: t.x + 0.15, y: t.y + 0.05, w: 2.6, h: 0.35,\n      fontSize: 11, fontFace: \"Arial\", color: C.white, bold: true, margin: 0,\n    });\n    s.addText(t.desc, {\n      x: t.x + 0.15, y: t.y + 0.4, w: 2.6, h: 0.35,\n      fontSize: 9, fontFace: \"Calibri\", color: C.lt, margin: 0,\n    });\n  });\n\n  // Broader ecosystem (2 cross-listed repos)\n  s.addShape(pres.shapes.RECTANGLE, {\n    x: 6.7, y: 3.05, w: 2.9, h: 0.85, fill: { color: C.cardBg2 }, shadow: mkSh(),\n  });\n  s.addShape(pres.shapes.RECTANGLE, {\n    x: 6.7, y: 3.05, w: 0.06, h: 0.85, fill: { color: C.accent3 },\n  });\n  s.addText(\"oh-my-codex\", {\n    x: 6.85, y: 3.1, w: 2.6, h: 0.35,\n    fontSize: 11, fontFace: \"Arial\", color: C.white, bold: true, margin: 0,\n  });\n  s.addText(\"Hooks, agent teams, HUDs for Codex\", {\n    x: 6.85, y: 3.45, w: 2.6, h: 0.35,\n    fontSize: 9, fontFace: \"Calibri\", color: C.lt, margin: 0,\n  });\n\n  s.addShape(pres.shapes.RECTANGLE, {\n    x: 6.7, y: 4.05, w: 2.9, h: 0.85, fill: { color: C.cardBg2 }, shadow: mkSh(),\n  });\n  s.addShape(pres.shapes.RECTANGLE, {\n    x: 6.7, y: 4.05, w: 0.06, h: 0.85, fill: { color: C.accent3 },\n  });\n  s.addText(\"agent-skills\", {\n    x: 6.85, y: 4.1, w: 2.6, h: 0.35,\n    fontSize: 11, fontFace: \"Arial\", color: C.white, bold: true, margin: 0,\n  });\n  s.addText(\"Production-grade engineering skills\", {\n    x: 6.85, y: 4.45, w: 2.6, h: 0.35,\n    fontSize: 9, fontFace: \"Calibri\", color: C.lt, margin: 0,\n  });\n\n  // Legend / key\n  s.addShape(pres.shapes.RECTANGLE, { x: 0.3, y: 4.15, w: 0.2, h: 0.2, fill: { color: C.accent2 } });\n  s.addText(\"Core Claude Code Tools (5)\", {\n    x: 0.6, y: 4.1, w: 2.5, h: 0.3,\n    fontSize: 10, fontFace: \"Calibri\", color: C.lt, margin: 0,\n  });\n  s.addShape(pres.shapes.RECTANGLE, { x: 0.3, y: 4.45, w: 0.2, h: 0.2, fill: { color: C.accent3 } });\n  s.addText(\"Broader Ecosystem (+2 cross-listed)\", {\n    x: 0.6, y: 4.4, w: 2.5, h: 0.3,\n    fontSize: 10, fontFace: \"Calibri\", color: C.lt, margin: 0,\n  });\n\n  s.addText(\"At least 7 repos broadly serve as Claude Code skills, guides, best-practice collections, or multi-tool switchers.\", {\n    x: 3.0, y: 4.55, w: 3.8, h: 0.35,\n    fontSize: 9, fontFace: \"Calibri\", color: C.lt, italic: true, margin: 0,\n  });\n\n  // ════════════════════════════════════════════════════════════════\n  // SLIDE 7 – Community Engagement\n  // ════════════════════════════════════════════════════════════════\n  s = pres.addSlide();\n  s.background = { color: C.darkBg };\n  topBar(s);\n\n  s.addText(\"hermes-agent Draws 78 PRs and 42 Pushes — Community Activity Varies Widely\", {\n    x: 0.6, y: 0.25, w: 8.8, h: 0.55,\n    fontSize: 20, fontFace: \"Arial Black\", color: C.white, bold: true, margin: 0,\n  });\n\n  // Grouped bar chart: PRs and Pushes for top repos by activity\n  const engLabels = [\n    \"hermes-agent\",\n    \"multica\",\n    \"oh-my-codex\",\n    \"graphify\",\n    \"rtk\",\n    \"cc-switch\",\n    \"opendataloader-pdf\",\n    \"reverse-SynthID\",\n    \"DeepTutor\",\n    \"InstantSpaceSwitcher\",\n    \"caveman\",\n    \"Recordly\",\n  ];\n  const engPRs    = [78, 7, 2, 5, 5, 2, 1, 1, 0, 0, 1, 1];\n  const engPushes = [42, 35, 10, 6, 3, 2, 3, 2, 2, 2, 1, 1];\n\n  s.addChart(pres.charts.BAR, [\n    { name: \"PRs\",    labels: engLabels, values: engPRs },\n    { name: \"Pushes\", labels: engLabels, values: engPushes },\n  ], {\n    x: 0.3, y: 0.85, w: 6.5, h: 3.8,\n    barDir: \"bar\",\n    barGrouping: \"clustered\",\n    chartColors: [C.accent, C.accent2],\n    showTitle: false,\n    showLegend: true,\n    legendPos: \"b\",\n    legendFontSize: 10,\n    legendColor: C.lt,\n    catAxisLabelColor: C.lt,\n    catAxisLabelFontSize: 9,\n    valAxisLabelColor: C.lt,\n    valAxisLabelFontSize: 9,\n    valGridLine: { color: C.cardBg2, size: 0.5 },\n    catGridLine: { style: \"none\" },\n    showValue: true,\n    dataLabelPosition: \"outEnd\",\n    dataLabelColor: C.lt,\n    dataLabelFontSize: 8,\n  });\n\n  // Right panel: key insight\n  s.addShape(pres.shapes.RECTANGLE, { x: 7.0, y: 0.85, w: 2.7, h: 1.3, fill: { color: C.cardBg }, shadow: mkSh() });\n  s.addShape(pres.shapes.RECTANGLE, { x: 7.0, y: 0.85, w: 2.7, h: 0.06, fill: { color: C.accent } });\n  s.addText(\"78 PRs\", {\n    x: 7.1, y: 0.95, w: 2.5, h: 0.55,\n    fontSize: 26, fontFace: \"Arial Black\", color: C.accent, bold: true, margin: 0,\n  });\n  s.addText(\"hermes-agent alone in 24h\\nDwarfs all other repos\", {\n    x: 7.1, y: 1.5, w: 2.5, h: 0.55,\n    fontSize: 10, fontFace: \"Calibri\", color: C.lt, margin: 0,\n  });\n\n  s.addShape(pres.shapes.RECTANGLE, { x: 7.0, y: 2.3, w: 2.7, h: 1.3, fill: { color: C.cardBg }, shadow: mkSh() });\n  s.addShape(pres.shapes.RECTANGLE, { x: 7.0, y: 2.3, w: 2.7, h: 0.06, fill: { color: C.accent2 } });\n  s.addText(\"35 Pushes\", {\n    x: 7.1, y: 2.4, w: 2.5, h: 0.55,\n    fontSize: 26, fontFace: \"Arial Black\", color: C.accent2, bold: true, margin: 0,\n  });\n  s.addText(\"multica-ai/multica\\n2nd most active repo\", {\n    x: 7.1, y: 2.95, w: 2.5, h: 0.55,\n    fontSize: 10, fontFace: \"Calibri\", color: C.lt, margin: 0,\n  });\n\n  s.addShape(pres.shapes.RECTANGLE, { x: 7.0, y: 3.75, w: 2.7, h: 1.1, fill: { color: C.cardBg }, shadow: mkSh() });\n  s.addShape(pres.shapes.RECTANGLE, { x: 7.0, y: 3.75, w: 2.7, h: 0.06, fill: { color: C.accent5 } });\n  s.addText(\"8 / 20\", {\n    x: 7.1, y: 3.85, w: 2.5, h: 0.55,\n    fontSize: 26, fontFace: \"Arial Black\", color: C.accent5, bold: true, margin: 0,\n  });\n  s.addText(\"Repos have zero PRs\\nEarly-stage virality, not\\nmature community dev\", {\n    x: 7.1, y: 4.35, w: 2.5, h: 0.45,\n    fontSize: 10, fontFace: \"Calibri\", color: C.lt, margin: 0,\n  });\n\n  // ════════════════════════════════════════════════════════════════\n  // SLIDE 8 – Key Takeaways\n  // ════════════════════════════════════════════════════════════════\n  s = pres.addSlide();\n  s.background = { color: C.darkBg };\n  topBar(s);\n\n  s.addText(\"Key Takeaways: AI Coding Agents Are GitHub’s Hottest Category\", {\n    x: 0.6, y: 0.25, w: 8.8, h: 0.55,\n    fontSize: 24, fontFace: \"Arial Black\", color: C.white, bold: true, margin: 0,\n  });\n\n  // Generate icons\n  const iconRobot = await iconPng(FaRobot, \"#\" + C.accent, 256);\n  // Wait, no # in colors! Let me fix\n  const iconRobot2 = await iconPng(FaRobot, C.accent, 256);\n  // Actually iconPng takes a CSS color string for the SVG renderIconSvg, which needs # prefix for the SVG\n  // But the sharp conversion just renders the SVG, so the # is fine in the SVG markup\n  // The no-# rule applies to PptxGenJS color options, not to SVG rendering\n  // Let me just use hex strings with # for the icon SVG rendering (that's CSS/SVG, not PptxGenJS)\n\n  const icons = [\n    await iconPng(FaRobot, \"#06B6D4\", 256),\n    await iconPng(FaCode,  \"#8B5CF6\", 256),\n    await iconPng(FaStar,  \"#F59E0B\", 256),\n    await iconPng(FaUsers, \"#10B981\", 256),\n    await iconPng(FaBolt,  \"#EF4444\", 256),\n  ];\n\n  const takeaways = [\n    {\n      icon: icons[0],\n      title: \"AI coding agents dominate GitHub trending\",\n      body: \"14 of the top 20 repos (70%) are AI coding agent tools, skills, or related resources — an unprecedented concentration in a single theme.\",\n    },\n    {\n      icon: icons[1],\n      title: \"Claude Code has spawned a full ecosystem overnight\",\n      body: \"At least 7 repos are specifically Claude Code skills, guides, best-practice collections, or multi-tool switchers, indicating rapid community formation around Anthropic’s coding tool.\",\n    },\n    {\n      icon: icons[2],\n      title: \"Python leads, but TypeScript is the runner-up\",\n      body: \"Python powers 35% of trending repos (AI/ML core), while TypeScript (20%) drives agent UIs and developer experience layers.\",\n    },\n    {\n      icon: icons[3],\n      title: \"Community engagement is top-heavy\",\n      body: \"The #1 repo (hermes-agent) attracted 78 PRs in 24 hours; most repos below #8 show minimal collaborative activity, suggesting early-stage virality.\",\n    },\n    {\n      icon: icons[4],\n      title: \"Token efficiency is a hot sub-theme\",\n      body: \"Multiple repos (caveman, rtk) focus on reducing LLM token consumption — signaling cost-consciousness as AI coding tools scale.\",\n    },\n  ];\n\n  takeaways.forEach((tk, i) => {\n    const y = 1.0 + i * 0.85;\n    // Card background\n    s.addShape(pres.shapes.RECTANGLE, { x: 0.6, y, w: 8.8, h: 0.75, fill: { color: C.cardBg }, shadow: mkSh() });\n    // Icon\n    s.addImage({ data: tk.icon, x: 0.75, y: y + 0.13, w: 0.5, h: 0.5 });\n    // Title\n    s.addText(tk.title, {\n      x: 1.4, y: y + 0.02, w: 7.8, h: 0.3,\n      fontSize: 13, fontFace: \"Arial\", color: C.white, bold: true, margin: 0,\n    });\n    // Body\n    s.addText(tk.body, {\n      x: 1.4, y: y + 0.32, w: 7.8, h: 0.4,\n      fontSize: 10, fontFace: \"Calibri\", color: C.lt, margin: 0,\n    });\n  });\n\n  // Footer\n  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 5.0, w: 10, h: 0.625, fill: { color: C.cardBg } });\n  s.addText(\"Data Source: OSSInsight  |  ossinsight.io  |  May 2026\", {\n    x: 0.8, y: 5.05, w: 8.4, h: 0.5,\n    fontSize: 11, fontFace: \"Calibri\", color: C.lt, valign: \"middle\", margin: 0,\n  });\n\n  // ── Write file ────────────────────────────────────────────────────\n  await pres.writeFile({ fileName: \"/app/output/final_deck.pptx\" });\n  console.log(\"Presentation saved to /app/output/final_deck.pptx\");\n}\n\nmain().catch(err => { console.error(err); process.exit(1); });\n", "numLines": 640, "startLine": 1, "totalLines": 640}}

