const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const {
  FaRobot, FaCode, FaStar, FaUsers, FaBolt
} = require("react-icons/fa");

// ── Color Palette: "Midnight Tech" ──────────────────────────────────
const C = {
  darkBg:   "0F172A",
  cardBg:   "1E293B",
  cardBg2:  "334155",
  accent:   "06B6D4",   // cyan
  accent2:  "8B5CF6",   // purple
  accent3:  "F59E0B",   // amber
  accent4:  "10B981",   // emerald
  accent5:  "EF4444",   // red
  white:    "FFFFFF",
  lt:       "94A3B8",   // light text
  mt:       "CBD5E1",   // mid text
};

// ── Icon helpers ────────────────────────────────────────────────────
function renderIconSvg(IC, color, size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IC, { color, size: String(size) })
  );
}
async function iconPng(IC, color, size = 256) {
  const svg = renderIconSvg(IC, color, size);
  const buf = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + buf.toString("base64");
}

// ── Fresh shadow factory (avoid object reuse) ──────────────────────
const mkSh = () => ({ type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.15 });

async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "OSSInsight Analysis";
  pres.title = "GitHub Trending Repos Snapshot: The Rise of AI Coding Agents & Claude Code Skills";

  // Shared: top accent bar helper
  const topBar = (s) => s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent } });

  // ════════════════════════════════════════════════════════════════
  // SLIDE 1 – Title
  // ════════════════════════════════════════════════════════════════
  let s = pres.addSlide();
  s.background = { color: C.darkBg };
  topBar(s);

  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 5.0, w: 10, h: 0.625, fill: { color: C.cardBg } });
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 5.0, w: 0.06, h: 0.625, fill: { color: C.accent2 } });

  s.addText("GitHub Trending Repos Snapshot", {
    x: 0.8, y: 1.0, w: 8.4, h: 1.0,
    fontSize: 40, fontFace: "Arial Black", color: C.white, bold: true, margin: 0,
  });
  s.addText("The Rise of AI Coding Agents & Claude Code Skills", {
    x: 0.8, y: 2.1, w: 8.4, h: 0.65,
    fontSize: 23, fontFace: "Arial", color: C.accent, margin: 0,
  });
  s.addText("Powered by OSSInsight — 10.6B+ GitHub Events Analyzed in Real Time", {
    x: 0.8, y: 3.0, w: 8.4, h: 0.4,
    fontSize: 14, fontFace: "Calibri", color: C.lt, margin: 0,
  });
  s.addText("Top 20 Trending Repositories — Past 24 Hours", {
    x: 0.8, y: 3.5, w: 8.4, h: 0.35,
    fontSize: 13, fontFace: "Calibri", color: C.mt, margin: 0,
  });
  s.addText("May 2026  |  Data Source: ossinsight.io", {
    x: 0.5, y: 5.05, w: 9.0, h: 0.5,
    fontSize: 11, fontFace: "Calibri", color: C.lt, valign: "middle", margin: 0,
  });

  // ════════════════════════════════════════════════════════════════
  // SLIDE 2 – Platform Overview
  // ════════════════════════════════════════════════════════════════
  s = pres.addSlide();
  s.background = { color: C.darkBg };
  topBar(s);

  s.addText("OSSInsight Tracks 10.6 Billion GitHub Events in Real Time", {
    x: 0.6, y: 0.25, w: 8.8, h: 0.55,
    fontSize: 24, fontFace: "Arial Black", color: C.white, bold: true, margin: 0,
  });
  s.addText("A free analytics platform providing deep insights into open-source repositories, developers, and organizations", {
    x: 0.6, y: 0.85, w: 8.8, h: 0.45,
    fontSize: 12, fontFace: "Calibri", color: C.lt, margin: 0,
  });

  // Three large stat cards
  const stats = [
    { val: "10.6B+", sub: "GitHub Events\nTracked", col: C.accent },
    { val: "20", sub: "Top Trending\nRepos Analyzed", col: C.accent2 },
    { val: "70%", sub: "AI Coding Agent\nRelated Repos", col: C.accent3 },
  ];
  stats.forEach((st, i) => {
    const x = 0.6 + i * 3.1;
    s.addShape(pres.shapes.RECTANGLE, { x, y: 1.55, w: 2.8, h: 1.4, fill: { color: C.cardBg }, shadow: mkSh() });
    s.addShape(pres.shapes.RECTANGLE, { x, y: 1.55, w: 2.8, h: 0.06, fill: { color: st.col } });
    s.addText(st.val, {
      x: x + 0.1, y: 1.65, w: 2.6, h: 0.7,
      fontSize: 32, fontFace: "Arial Black", color: st.col, bold: true, align: "center", margin: 0,
    });
    s.addText(st.sub, {
      x: x + 0.1, y: 2.35, w: 2.6, h: 0.5,
      fontSize: 11, fontFace: "Calibri", color: C.lt, align: "center", margin: 0,
    });
  });

  // Metrics row
  s.addText("Key Metrics Tracked by OSSInsight", {
    x: 0.6, y: 3.25, w: 8.8, h: 0.3,
    fontSize: 14, fontFace: "Arial", color: C.white, bold: true, margin: 0,
  });
  const metrics = [
    { label: "Stars", col: C.accent },
    { label: "Forks", col: C.accent2 },
    { label: "Commits", col: C.accent4 },
    { label: "Pull Requests", col: C.accent3 },
    { label: "Issues & Reviews", col: C.accent5 },
  ];
  metrics.forEach((m, i) => {
